create type public.app_role as enum ('ADMIN','GESTOR','EDITOR','DIRETORIA');
create type public.action_origin as enum ('engenharia','execucao','financeiro','outro');
create type public.action_status as enum ('aberto','em_andamento','concluido');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text,role public.app_role not null default 'DIRETORIA',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contracts(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,contract_value numeric(18,2) not null check(contract_value>=0),start_date date not null,end_date date not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table public.subcontracts(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),code text not null,name text not null,municipality text,active boolean not null default true,created_at timestamptz not null default now(),unique(contract_id,code));
create table public.annual_targets(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),year int not null check(year between 2000 and 2100),target_economies int not null check(target_economies>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(contract_id,year));
create table public.monthly_financials(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),reference_month int not null check(reference_month between 1 and 12),reference_year int not null,amount numeric(18,2) not null check(amount>=0),notes text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),active boolean not null default true);
create unique index monthly_financials_active_competence on public.monthly_financials(contract_id,reference_year,reference_month) where active;
create table public.weekly_progress(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),reference_date date not null,economies_available int not null check(economies_available>=0),economies_executed int not null check(economies_executed>=0),network_approved_m numeric(14,2) not null check(network_approved_m>=0),network_executed_m numeric(14,2) not null check(network_executed_m>=0),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),active boolean not null default true);
create unique index weekly_progress_active_date on public.weekly_progress(contract_id,reference_date) where active;
create table public.projection_cycles(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),base_month int not null check(base_month between 1 and 12),base_year int not null,avg_weekly_economies_available numeric,avg_weekly_economies_executed numeric,avg_weekly_network_approved_m numeric,avg_weekly_network_executed_m numeric,calculated_at timestamptz not null default now(),unique(contract_id,base_year,base_month));
create table public.action_plans(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),origin public.action_origin not null,title text not null,description text not null,action text not null,responsible text,due_date date,status public.action_status not null default 'aberto',created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,user_id uuid,entity text not null,entity_id uuid,action text not null,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.contracts enable row level security;alter table public.subcontracts enable row level security;alter table public.annual_targets enable row level security;alter table public.monthly_financials enable row level security;alter table public.weekly_progress enable row level security;alter table public.projection_cycles enable row level security;alter table public.action_plans enable row level security;alter table public.audit_logs enable row level security;
revoke all on all tables in schema public from anon;grant select on public.profiles,public.contracts,public.subcontracts,public.annual_targets,public.monthly_financials,public.weekly_progress,public.projection_cycles,public.action_plans to authenticated;grant insert,update on public.monthly_financials,public.weekly_progress,public.action_plans to authenticated;grant select on public.audit_logs to authenticated;
grant insert,update,delete on public.profiles,public.contracts,public.subcontracts,public.annual_targets,public.monthly_financials,public.weekly_progress,public.projection_cycles,public.action_plans to authenticated;
create schema if not exists private;revoke all on schema private from public,anon;grant usage on schema private to authenticated;
create function private.current_app_role() returns public.app_role language sql stable security definer set search_path='' as $$select role from public.profiles where id=(select auth.uid())$$;
revoke all on function private.current_app_role() from public,anon;grant execute on function private.current_app_role() to authenticated;
create policy profiles_self_read on public.profiles for select to authenticated using(id=(select auth.uid()) or private.current_app_role()='ADMIN');
create policy read_contracts on public.contracts for select to authenticated using((select auth.uid()) is not null);create policy read_subcontracts on public.subcontracts for select to authenticated using((select auth.uid()) is not null);create policy read_targets on public.annual_targets for select to authenticated using((select auth.uid()) is not null);create policy read_financials on public.monthly_financials for select to authenticated using((select auth.uid()) is not null);create policy read_progress on public.weekly_progress for select to authenticated using((select auth.uid()) is not null);create policy read_cycles on public.projection_cycles for select to authenticated using((select auth.uid()) is not null);create policy read_actions on public.action_plans for select to authenticated using((select auth.uid()) is not null);
create policy read_audit on public.audit_logs for select to authenticated using(private.current_app_role() in ('ADMIN','GESTOR'));
create policy admin_profiles on public.profiles for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_contracts on public.contracts for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_subcontracts on public.subcontracts for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_targets on public.annual_targets for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_financials on public.monthly_financials for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_progress on public.weekly_progress for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_cycles on public.projection_cycles for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');create policy admin_actions on public.action_plans for all to authenticated using(private.current_app_role()='ADMIN') with check(private.current_app_role()='ADMIN');
create policy write_financials_i on public.monthly_financials for insert to authenticated with check(private.current_app_role() in ('ADMIN','EDITOR') and created_by=(select auth.uid()));create policy write_financials_u on public.monthly_financials for update to authenticated using(private.current_app_role() in ('ADMIN','EDITOR')) with check(private.current_app_role() in ('ADMIN','EDITOR'));
create policy write_progress_i on public.weekly_progress for insert to authenticated with check(private.current_app_role() in ('ADMIN','EDITOR') and created_by=(select auth.uid()));create policy write_progress_u on public.weekly_progress for update to authenticated using(private.current_app_role() in ('ADMIN','EDITOR')) with check(private.current_app_role() in ('ADMIN','EDITOR'));
create policy write_actions_i on public.action_plans for insert to authenticated with check(private.current_app_role() in ('ADMIN','EDITOR') and created_by=(select auth.uid()));create policy write_actions_u on public.action_plans for update to authenticated using(private.current_app_role() in ('ADMIN','EDITOR')) with check(private.current_app_role() in ('ADMIN','EDITOR'));
create function public.capture_audit() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.audit_logs(user_id,entity,entity_id,action,old_data,new_data) values((select auth.uid()),TG_TABLE_NAME,coalesce(NEW.id,OLD.id),TG_OP,case when TG_OP<>'INSERT' then to_jsonb(OLD) end,case when TG_OP<>'DELETE' then to_jsonb(NEW) end);return coalesce(NEW,OLD);end$$;
revoke all on function public.capture_audit() from public,anon,authenticated;
create trigger audit_contracts after insert or update or delete on public.contracts for each row execute function public.capture_audit();create trigger audit_targets after insert or update or delete on public.annual_targets for each row execute function public.capture_audit();create trigger audit_financials after insert or update or delete on public.monthly_financials for each row execute function public.capture_audit();create trigger audit_progress after insert or update or delete on public.weekly_progress for each row execute function public.capture_audit();create trigger audit_actions after insert or update or delete on public.action_plans for each row execute function public.capture_audit();
